        colors[ImGuiCol_TableBorderStrong] = ImVec4(0.70f, 0.70f, 0.73f, 1.00f);
        colors[ImGuiCol_TableBorderLight] = ImVec4(0.82f, 0.82f, 0.85f, 1.00f);
        colors[ImGuiCol_TableRowBg] = ImVec4(0.96f, 0.96f, 0.97f, 1.00f);
